CREATE TYPE public.app_role AS ENUM ('admin');
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL, UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.has_role(_user_id uuid, _role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role) $$;
REVOKE ALL ON FUNCTION public.has_role(uuid,public.app_role) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.has_role(uuid,public.app_role) TO authenticated;
CREATE POLICY own_role ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE TABLE public.media (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), path text UNIQUE NOT NULL, filename text NOT NULL, mime_type text NOT NULL CHECK(mime_type IN ('image/jpeg','image/png','image/webp')), size_bytes integer NOT NULL CHECK(size_bytes>0 AND size_bytes<=10485760), approved boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.media TO authenticated; GRANT ALL ON public.media TO service_role;
ALTER TABLE public.media ENABLE ROW LEVEL SECURITY;
CREATE POLICY admin_media ON public.media FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.content (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), kind text NOT NULL CHECK(kind IN ('slideshow','services','doctors','gallery','youtube','testimonials')), title text NOT NULL CHECK(length(title) BETWEEN 1 AND 180), description text NOT NULL DEFAULT '' CHECK(length(description)<=10000), category text NOT NULL DEFAULT '', display_order integer NOT NULL DEFAULT 0 CHECK(display_order>=0), published boolean NOT NULL DEFAULT false, featured boolean NOT NULL DEFAULT false, image_id uuid REFERENCES public.media(id) ON DELETE RESTRICT, data jsonb NOT NULL DEFAULT '{}'::jsonb, updated_at timestamptz NOT NULL DEFAULT now(), created_at timestamptz NOT NULL DEFAULT now(), CHECK(kind<>'youtube' OR (data->>'video_id') ~ '^[A-Za-z0-9_-]{11}$'), CHECK(kind<>'testimonials' OR NOT published OR data->>'verified'='true'), CHECK(kind<>'services' OR NOT published OR data->>'verified'='true'), CHECK(kind<>'doctors' OR NOT published OR data->>'verified'='true'));
GRANT SELECT ON public.content TO anon; GRANT SELECT,INSERT,UPDATE,DELETE ON public.content TO authenticated; GRANT ALL ON public.content TO service_role;
ALTER TABLE public.content ENABLE ROW LEVEL SECURITY;
CREATE POLICY published_content ON public.content FOR SELECT TO anon,authenticated USING(published);
CREATE POLICY admin_content ON public.content FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE INDEX content_kind_order ON public.content(kind,published,display_order);
CREATE TABLE public.website_settings (id integer PRIMARY KEY DEFAULT 1 CHECK(id=1), data jsonb NOT NULL DEFAULT '{}'::jsonb, slideshow_interval integer NOT NULL DEFAULT 20 CHECK(slideshow_interval BETWEEN 15 AND 30), upload_limit_mb integer NOT NULL DEFAULT 5 CHECK(upload_limit_mb BETWEEN 1 AND 10), logo_id uuid REFERENCES public.media(id) ON DELETE RESTRICT, updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.website_settings TO anon; GRANT SELECT,INSERT,UPDATE ON public.website_settings TO authenticated; GRANT ALL ON public.website_settings TO service_role;
ALTER TABLE public.website_settings ENABLE ROW LEVEL SECURITY;
CREATE POLICY public_settings ON public.website_settings FOR SELECT TO anon,authenticated USING(true);
CREATE POLICY admin_settings ON public.website_settings FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
INSERT INTO public.website_settings(id,data) VALUES(1,'{"name":"Drishti Eye Care","tagline":"Affordable Care for Priceless Sight……","addressLines":["17, Vidhya Nagar, Phase 2","Near Her Health Hospital","Narmadapuram Road","Bhopal, Madhya Pradesh"],"phones":["99931 75735","70490 12629"],"phoneHref":"tel:+919993175735","whatsappHref":"https://wa.me/919993175735","directionsHref":"https://www.google.com/maps/dir/?api=1&destination=Drishti+Eye+Care+Vidhya+Nagar+Phase+2+Narmadapuram+Road+Bhopal","mapEmbed":"https://www.google.com/maps?q=Vidhya+Nagar+Phase+2+Narmadapuram+Road+Bhopal&output=embed","openingHours":"","facebook":"","instagram":"","youtube":""}');
CREATE TABLE public.appointments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), patient_name text NOT NULL CHECK(length(patient_name) BETWEEN 2 AND 80), phone text NOT NULL CHECK(phone ~ '^[0-9]{10,15}$'), email text NOT NULL DEFAULT '' CHECK(email='' OR email ~ '^[^@ ]+@[^@ ]+\.[^@ ]+$'), preferred_date date, preferred_time text NOT NULL DEFAULT '' CHECK(length(preferred_time)<=80), reason text NOT NULL DEFAULT '' CHECK(length(reason)<=500), status text NOT NULL DEFAULT 'New' CHECK(status IN ('New','Contacted','Confirmed','Completed','Cancelled')), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,UPDATE,DELETE ON public.appointments TO authenticated; GRANT ALL ON public.appointments TO service_role;
ALTER TABLE public.appointments ENABLE ROW LEVEL SECURITY;
CREATE POLICY admin_appointments ON public.appointments FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE INDEX appointments_created ON public.appointments(created_at DESC); CREATE INDEX appointments_status ON public.appointments(status);
CREATE TABLE public.appointment_rate_limits (key text PRIMARY KEY, last_submission timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.appointment_rate_limits TO service_role;
ALTER TABLE public.appointment_rate_limits ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.submit_appointment(_name text,_phone text,_email text,_date date,_time text,_reason text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE new_id uuid; BEGIN INSERT INTO public.appointment_rate_limits(key) VALUES(_phone) ON CONFLICT(key) DO UPDATE SET last_submission=now() WHERE appointment_rate_limits.last_submission < now()-interval '60 seconds'; IF NOT FOUND THEN RAISE EXCEPTION 'Please wait a minute before submitting another request.'; END IF; INSERT INTO public.appointments(patient_name,phone,email,preferred_date,preferred_time,reason) VALUES(_name,_phone,_email,_date,_time,_reason) RETURNING id INTO new_id; RETURN new_id; END $$;
REVOKE ALL ON FUNCTION public.submit_appointment(text,text,text,date,text,text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.submit_appointment(text,text,text,date,text,text) TO service_role;
CREATE FUNCTION public.touch_content() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN NEW.updated_at=now(); RETURN NEW; END $$;
CREATE TRIGGER content_updated BEFORE UPDATE ON public.content FOR EACH ROW EXECUTE FUNCTION public.touch_content();
CREATE TRIGGER settings_updated BEFORE UPDATE ON public.website_settings FOR EACH ROW EXECUTE FUNCTION public.touch_content();
CREATE POLICY admin_image_select ON storage.objects FOR SELECT TO authenticated USING(bucket_id='clinic-images' AND public.has_role(auth.uid(),'admin'));
CREATE POLICY admin_image_insert ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='clinic-images' AND public.has_role(auth.uid(),'admin') AND lower(storage.extension(name)) IN ('jpg','jpeg','png','webp'));
CREATE POLICY admin_image_update ON storage.objects FOR UPDATE TO authenticated USING(bucket_id='clinic-images' AND public.has_role(auth.uid(),'admin')) WITH CHECK(bucket_id='clinic-images' AND public.has_role(auth.uid(),'admin'));
CREATE POLICY admin_image_delete ON storage.objects FOR DELETE TO authenticated USING(bucket_id='clinic-images' AND public.has_role(auth.uid(),'admin') AND NOT EXISTS(SELECT 1 FROM public.media WHERE path=name));
CREATE POLICY approved_image_read ON storage.objects FOR SELECT TO anon,authenticated USING(bucket_id='clinic-images' AND EXISTS(SELECT 1 FROM public.media m JOIN public.content c ON c.image_id=m.id WHERE m.path=name AND m.approved AND c.published) OR bucket_id='clinic-images' AND EXISTS(SELECT 1 FROM public.media m JOIN public.website_settings s ON s.logo_id=m.id WHERE m.path=name AND m.approved));